function parseNumber(text) {
  if (typeof text !== "string" || text.trim() === "") {
    throw new TypeError("Expected a non-empty string");
  }
  const value = Number(text);
  if (!Number.isFinite(value)) {
    throw new RangeError("Expected a finite number");
  }
  return value;
}
